with joined as (select src.*, c.name, c.credit_limit, c.signup_date from sessions src left join customers c on src.customer_id = c.id) select device, date_trunc('quarter', started_at) as quarter_start, sort_array(collect_set(browser)) as browser_list, round(avg(credit_limit), 2) as avg_credit_limit, (unix_timestamp(max(started_at)) - unix_timestamp(min(started_at))) / 60 as span_minutes, max(started_at) as last_started_at, sum(case when device = 'desktop' then credit_limit else 0 end) as desktop_credit_limit from joined group by device, date_trunc('quarter', started_at) having span_minutes >= 0
